#!/usr/bin/env python3
from pathlib import Path
import sys

ROOT=Path.cwd()
if not (ROOT/'settings.gradle.kts').exists() or not (ROOT/'app/build.gradle.kts').exists():
    raise SystemExit('ERROR: شغّل هذا الملف من جذر مشروع AL-thmany-Extractor داخل Codespaces')

# 1) Add test-only WhatsApp simulator module.
settings=ROOT/'settings.gradle.kts'
s=settings.read_text(encoding='utf-8')
if 'include(":whatsapp-simulator")' not in s:
    anchor='include(":app")'
    if anchor not in s:
        raise SystemExit('ERROR: لم أجد include(":app") في settings.gradle.kts')
    s=s.replace(anchor, anchor+'\ninclude(":whatsapp-simulator")', 1)
    settings.write_text(s, encoding='utf-8')

# 2) Add Android instrumentation dependencies without touching production dependencies.
app=ROOT/'app/build.gradle.kts'
s=app.read_text(encoding='utf-8')
deps=[
    '    androidTestImplementation("androidx.test.ext:junit:1.2.1")',
    '    androidTestImplementation("androidx.test:runner:1.6.2")',
    '    androidTestImplementation("androidx.test:core-ktx:1.6.1")',
    '    androidTestImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.10.2")',
]
missing=[d for d in deps if d not in s]
if missing:
    anchor='    testImplementation("junit:junit:4.13.2")'
    if anchor not in s:
        raise SystemExit('ERROR: لم أجد testImplementation junit في app/build.gradle.kts')
    s=s.replace(anchor, anchor+'\n'+'\n'.join(missing), 1)
    app.write_text(s, encoding='utf-8')

